#include "FoldbackSession.h"

// foldback.h is generated by cbindgen with `language = "C"` and
// `cpp_compat = true` — the latter added by this binding (Unity/Godot
// never needed it: C# P/Invoke and gdext never compile this header at
// all), which makes cbindgen emit its own `#ifdef __cplusplus extern "C"`
// guard and avoid a real enum/typedef redefinition error C++ hits that C
// doesn't. See cbindgen.toml's comment for the full story.
#include "foldback.h"

FFoldbackSession::~FFoldbackSession()
{
	if (Handle)
	{
		foldback_session_destroy(Handle);
		Handle = nullptr;
	}
}

FFoldbackSession::FFoldbackSession(FFoldbackSession&& Other) noexcept
	: Handle(Other.Handle)
	, LastError(MoveTemp(Other.LastError))
{
	Other.Handle = nullptr;
}

FFoldbackSession& FFoldbackSession::operator=(FFoldbackSession&& Other) noexcept
{
	if (this != &Other)
	{
		if (Handle)
		{
			foldback_session_destroy(Handle);
		}
		Handle = Other.Handle;
		LastError = MoveTemp(Other.LastError);
		Other.Handle = nullptr;
	}
	return *this;
}

void FFoldbackSession::SetLastErrorFromNative()
{
	const uintptr_t NeededLen = foldback_last_error(nullptr, 0);
	if (NeededLen == 0)
	{
		LastError.Empty();
		return;
	}
	TArray<char> Buf;
	Buf.SetNumUninitialized(static_cast<int32>(NeededLen) + 1);
	foldback_last_error(Buf.GetData(), Buf.Num());
	LastError = UTF8_TO_TCHAR(Buf.GetData());
}

bool FFoldbackSession::Configure(const FConfig& Config)
{
	if (Handle)
	{
		foldback_session_destroy(Handle);
		Handle = nullptr;
	}

	FoldbackConfig NativeConfig{};
	NativeConfig.tick_rate_hz = Config.TickRateHz;
	NativeConfig.peer_count = Config.PeerCount;
	NativeConfig.local_peer_id = Config.LocalPeerId;
	NativeConfig.retention = Config.Retention;
	FMemory::Memzero(NativeConfig.build_id);

	const FTCHARToUTF8 PathUtf8(*Config.RecordToPath);
	NativeConfig.record_to_path = Config.RecordToPath.IsEmpty() ? nullptr : PathUtf8.Get();

	Handle = foldback_session_create(&NativeConfig);
	if (!Handle)
	{
		SetLastErrorFromNative();
		return false;
	}
	LastError.Empty();
	return true;
}

bool FFoldbackSession::HashTick(uint64 Tick, TArrayView<const uint8> State)
{
	if (!Handle)
	{
		LastError = TEXT("session not configured — call Configure() first");
		return false;
	}
	const FoldbackStatus Status = foldback_hash_tick(Handle, Tick, State.GetData(), State.Num());
	if (Status != Ok)
	{
		SetLastErrorFromNative();
		return false;
	}
	return true;
}

