uint64 FFoldbackSession::PendingHashCount() const
{
	return Handle ? foldback_pending_hash_count(Handle) : 0;
}

TArray<TPair<uint64, uint64>> FFoldbackSession::TakePendingHashes(uint64 Max)
{
	TArray<TPair<uint64, uint64>> Out;
	if (!Handle || Max == 0)
	{
		return Out;
	}
	TArray<FoldbackPendingHash> Native;
	Native.SetNumUninitialized(static_cast<int32>(Max));
	const uintptr_t Drained = foldback_take_pending_hashes(Handle, Native.GetData(), Native.Num());
	Out.Reserve(static_cast<int32>(Drained));
	for (uintptr_t i = 0; i < Drained; ++i)
	{
		Out.Emplace(Native[i].tick, Native[i].hash);
	}
	return Out;
}

bool FFoldbackSession::CheckDivergence(uint64& OutTick)
{
	if (!Handle)
	{
		LastError = TEXT("session not configured — call Configure() first");
		return false;
	}
	bool bFound = false;
	uint64 Tick = 0;
	const FoldbackStatus Status = foldback_check_divergence(Handle, &bFound, &Tick);
	if (Status != Ok)
	{
		SetLastErrorFromNative();
		return false;
	}
	if (bFound)
	{
		OutTick = Tick;
	}
	return bFound;
}

